<?php $oauthClients=$user['role']==='admin'?App\Core\DB::all('SELECT id,name,redirect_uri,auth_method FROM oauth_clients ORDER BY created_at DESC,id'):[]; $oauthGrants=App\Core\DB::all('SELECT g.id,g.scopes,g.expires_at,g.last_used_at,g.auth_version,c.name FROM oauth_grants g JOIN oauth_clients c ON c.id=g.client_id WHERE g.user_id=? ORDER BY g.created_at DESC,g.id',[$user['id']]); $newOAuth=$_SESSION['new_oauth_client']??null;unset($_SESSION['new_oauth_client']); ?>
<section class="panel team-section" id="oauth"><div class="panel-header"><div><h2>Connexions OAuth — ChatGPT</h2><p>Connectez un client MCP qui utilise OAuth, avec autorisation de chaque utilisateur.</p></div><?= icon('lock') ?></div>
<?php if($user['role']==='admin'): ?>
<p class="help-text">Dans ChatGPT, choisissez OAuth puis « Client OAuth défini par l’utilisateur ». Copiez son URL de rappel dans le formulaire ci-dessous. Les métadonnées sont découvertes automatiquement après déploiement. DCR, CIMD et OpenID Connect ne sont pas proposés.</p>
<div class="stack oauth-endpoints"><?php foreach(['URL du serveur MCP'=>url('/mcp'),'URL d’autorisation'=>url('/oauth/authorize'),'URL du token'=>url('/oauth/token'),'URL de base du serveur d’autorisation'=>App\Models\OAuth::issuer(),'Ressource'=>url('/mcp')] as $label=>$value): ?><label><?= e($label) ?><input value="<?= e($value) ?>" readonly></label><?php endforeach; ?></div><p class="help-text">Portées par défaut, une par ligne : <code>read</code>, <code>write</code>. Portées de base : <code>read</code> et <code>offline_access</code>, pour permettre le renouvellement même lorsque ChatGPT utilise les portées des outils. Ajoutez <code>admin</code> uniquement pour administrer l’espace, puis cochez ce droit lors du consentement. Laissez l’URL d’enregistrement vide et OIDC désactivé.</p>
<?php if($newOAuth): ?><div class="notice"><strong>Identifiants du nouveau client</strong><label>ID client OAuth<input readonly value="<?= e($newOAuth['id']) ?>"></label><?php if($newOAuth['secret']!==null): ?><label>Secret du client OAuth — affiché une seule fois<input readonly autocomplete="off" value="<?= e($newOAuth['secret']) ?>"></label><?php else: ?><p>Client public : méthode <code>none</code>, sans secret. PKCE est obligatoire.</p><?php endif; ?></div><?php endif; ?>
<form method="post" action="/oauth/clients" class="stack"><?= csrf() ?><input type="hidden" name="_return" value="/settings#oauth"><label>Nom du client<input name="name" required maxlength="120" placeholder="ChatGPT"></label><label>URL de rappel exacte fournie par ChatGPT<input type="url" name="redirect_uri" required maxlength="1000" placeholder="Copiez l’URL affichée dans les paramètres OAuth de ChatGPT"></label><label>Méthode d’authentification au token<select name="auth_method"><option value="none">none — client public avec PKCE, sans secret</option><option value="client_secret_post">client_secret_post — secret dans la requête</option><option value="client_secret_basic">client_secret_basic — secret dans l’en-tête Basic</option></select></label><button class="button primary">Créer le client OAuth</button></form>
<?php foreach($oauthClients as $client): ?><article class="llm-profile"><h3><?= e($client['name']) ?></h3><p>ID : <code><?= e($client['id']) ?></code></p><p><?= e($client['auth_method']) ?> · <?= e($client['redirect_uri']) ?></p><form action="/oauth/clients/<?= e($client['id']) ?>/delete" method="post"><?= csrf() ?><input type="hidden" name="_return" value="/settings#oauth"><button class="text-button danger" data-confirm="Supprimer ce client OAuth et révoquer toutes ses connexions ?">Supprimer le client</button></form></article><?php endforeach; endif; ?>
<h3>Mes connexions autorisées</h3><?php foreach($oauthGrants as $grant): ?><article class="llm-profile"><h4><?= e($grant['name']) ?></h4><p>Droits : <?= e(implode(', ',json_decode($grant['scopes'],true))) ?><br>Expiration : <?= e($grant['expires_at']) ?> UTC · Dernier accès : <?= e($grant['last_used_at']??'Aucun') ?><?php if((int)$grant['auth_version']!==(int)$user['auth_version']): ?> · Invalidée par un changement d’accès<?php endif; ?></p><form method="post" action="/oauth/grants/<?= e($grant['id']) ?>/revoke"><?= csrf() ?><input type="hidden" name="_return" value="/settings#oauth"><button class="button subtle">Révoquer la connexion</button></form></article><?php endforeach; if(!$oauthGrants): ?><p class="muted">Aucune connexion OAuth autorisée pour votre compte.</p><?php endif; ?></section>
